create table wksp_doagmcp.ocg_groups_eu (
    group_id        number generated by default as identity not null enable,
    group_name      varchar2(200 byte) not null enable,
    country_code    varchar2(20 byte) not null enable,
    country_name    varchar2(100 byte) not null enable,
    city            varchar2(120 byte),
    website_url     varchar2(400 byte) not null enable,
    contact_email   varchar2(320 byte),
    focus_area      varchar2(200 byte),
    active_flag     char(1 byte) default 'Y',
    created_at      timestamp(6) with local time zone default systimestamp,
    updated_at      timestamp(6) with local time zone,
    country_code_id number
);

alter table wksp_doagmcp.ocg_groups_eu
    add
        check ( active_flag in ( 'Y', 'N' ) ) enable;

alter table wksp_doagmcp.ocg_groups_eu
    add constraint ocg_groups_eu_cc_chk check ( country_code = upper(country_code) ) enable;

alter table wksp_doagmcp.ocg_groups_eu
    add constraint ocg_groups_eu_uk unique ( group_name,
                                             country_code )
        using index enable;

alter table wksp_doagmcp.ocg_groups_eu add primary key ( group_id )
    using index enable;


